  for (const b of W.blocks) if (!b.park) { const [x, y] = T(b.x - b.w / 2, b.y - b.h / 2); c.fillStyle = '#7C7A76'; c.fillRect(x, y, b.w / sc, b.h / sc); c.fillStyle = 'rgba(0,0,0,.3)'; c.fillRect(x + b.w / sc * 0.7, y, b.w / sc * 0.3, b.h / sc); }
  for (const L of W.lanes) { c.strokeStyle = L.kind === 'w' ? 'rgba(255,255,255,.65)' : 'rgba(230,205,160,.9)'; c.lineWidth = L.kind === 'w' ? 1.2 : 2.2 * 1.2; c.setLineDash(L.kind === 'w' ? [3, 3] : []); c.beginPath(); L.pts.forEach((p, i) => { const [x, y] = T(p.x, p.y); i ? c.lineTo(x, y) : c.moveTo(x, y); }); c.stroke(); }
  c.setLineDash([]);
  for (const L of W.lanes) { const [x, y] = T(Math.max(0.5, Math.min(S - 0.5, L.start.x)), Math.max(0.5, Math.min(S - 0.5, L.start.y))); c.fillStyle = '#E8442E'; c.beginPath(); c.arc(x, y, 3.5, 0, 7); c.fill(); c.fillStyle = '#fff'; c.font = '700 9px Archivo,sans-serif'; c.textAlign = 'center'; c.fillText(L.unlock, x, y - 6); }
