const passTier = () => Math.min(PASS_N, Math.floor(G.pass.xp / PASS_STEP));
const passClaimable = () => { const t = passTier(); let n = 0; for (let i = 0; i < t; i++) { if (!G.pass.f[i]) n++; if (!G.pass.p[i]) n++; } return n; };
function passLabel(r) { return r.chest ? 'Coffre ' + CHEST[r.chest].n + (r.tk ? ' + ' + r.tk + ' tickets' : '') : grantLabel(r); }
