  if(!Number.isSafeInteger(amount)||amount<=0)return toast('Montant invalide.','bad');
  if(supplyLeft(G,a.card)<=0)return toast('Cette carte est épuisée.','bad');
  if(a.kind==='sealed'&&a.mine)return toast('Ton offre est déjà enregistrée.','bad');
  if(a.kind!=='sealed'&&a.lead==='Toi')return toast('Tu es déjà en tête.','good');
  if(amount<(a.kind==='sealed'?a.price:minNext(a)))return toast('Le prix a changé. Choisis une nouvelle offre.','bad');
  if(amount>G.c-engaged())return toast('Crédits disponibles insuffisants : certaines offres réservent déjà ton solde.','bad');
  if(a.kind==='sealed'){a.mine=amount;a.bids++;}else{a.price=amount;a.lead='Toi';a.bids++;if(a.t<6){a.t=6;a.extended=true;}}
