    el.onclick=e=>{const b=e.target.closest('[data-bid],[data-sealed],[data-inspect]');if(!b||b.disabled)return;const a=G.auctions.find(a=>a.id===+b.dataset.a&&!a.done);if(!a)return;if(b.hasAttribute('data-inspect'))return cardSheet(a.card,true);if(b.hasAttribute('data-sealed'))return sealedScene(a);placeBid(a,+b.dataset.amount);};
