        extras.push(box(.075,.24,.34,'#805f43',[.55,.20,side*.165],[0,side*.30,-.22]));
        extras.push(box(.10,.045,.25,'#c4ad7d',[.59,.30,side*.165],[0,side*.30,-.22]));
