   m.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('#include <opaque_fragment>','outgoingLight = outgoingLight / (vec3(1.0) + outgoingLight / 0.52);\n#include <opaque_fragment>');};
