 let state={user:null},available=false,loaded=false,stream=null,layer=null,authMode='login',busy=false,refreshPromise=null,stateRevision=0,friendFilter='',onlineOnly=false,viewKey='',returnFocus=null;const seen=new Set(),pending=new Map(),sections=new Map();
