// Event-driven navigation feedback; no permanent animation or animation-frame loop.
const NavigationPolish=(()=>{
 let cleanup=null;
 function init(){
  cleanup?.();const nav=document.querySelector('nav.tabs');if(!nav)return;
  const buttons=[...nav.querySelectorAll('button[data-t]')],abort=new AbortController();
  nav.classList.add('nav-polished');nav.setAttribute('aria-label','Navigation principale du jeu');
  const indicator=document.createElement('span');indicator.className='nav-active-indicator';indicator.setAttribute('aria-hidden','true');nav.appendChild(indicator);
  let selected=null;
  function sync(){const active=buttons.find(b=>b.classList.contains('on'));if(!active)return;
   for(const b of buttons){const id='t-'+b.dataset.t;b.setAttribute('aria-controls',id);if(b===active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}
   const width=Math.max(20,Math.min(46,active.offsetWidth*.55));indicator.style.width=width+'px';indicator.style.transform='translateX('+(active.offsetLeft+(active.offsetWidth-width)/2)+'px)';
   if(selected!==active){selected=active;nav.dataset.active=active.dataset.t;}
  }
  nav.addEventListener('keydown',e=>{const b=e.target.closest('button[data-t]');if(!b||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=buttons.indexOf(b),next=e.key==='Home'?buttons[0]:e.key==='End'?buttons.at(-1):buttons[(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length];next.focus();next.click();},{signal:abort.signal});
  const observer=new MutationObserver(sync);buttons.forEach(b=>observer.observe(b,{attributes:true,attributeFilter:['class']}));
  const resize=new ResizeObserver(sync);resize.observe(nav);buttons.forEach(b=>resize.observe(b));
  sync();cleanup=()=>{observer.disconnect();resize.disconnect();abort.abort();indicator.remove();};
 }
 return{init};
})();

// Account progress is separate from browser/device preferences and live matches.
const CloudProgress=(()=>{
 const ownerKey='owned-progress-owner-v1',guestKey='owned-guest-progress-v1';
 let offline=false;let owner=null,revision=0,timer=null,inflight=null,dirty=false,blocked=false,ready=false,version=0,label='Profil local',persistent=false,lastObserved='',lastSaved='';
 let tabId;try{tabId=sessionStorage.getItem('owned-save-tab');if(!tabId){tabId=crypto.randomUUID();sessionStorage.setItem('owned-save-tab',tabId);}}catch{tabId=String(Date.now())+Math.random();}
 const read=key=>{try{return JSON.parse(localStorage.getItem(key));}catch{return null;}};
 const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}};
 const pendingKey=()=>`owned-cloud-pending:${owner}:${tabId}`;
 function snapshot(){const {paused,dropToast,...progress}=G;return JSON.parse(JSON.stringify(progress));}
 function paintStatus(box){const error=label!=='Sauvegarde automatique activée'&&!!owner;box.querySelector('[data-cloud-status]').textContent=label;box.querySelector('[data-sync]').hidden=!error;box.querySelector('[data-sync]').textContent=blocked?'Recharger la progression':'Réessayer';}
 function status(text){if(label===text)return;label=text;document.querySelectorAll('.cloud-save-panel').forEach(paintStatus);}
 function schedule(){if(!timer&&!blocked&&dirty)timer=setTimeout(()=>{timer=null;flush().catch(()=>{});},5000);}
 async function api(method,data){const r=await fetch('/api/account/progress',{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(6000)});let out;try{out=await r.json();}catch{throw Error('Le serveur de sauvegarde ne répond pas.');}if(!r.ok){const e=Error(out.error||'Sauvegarde indisponible');e.status=r.status;throw e;}return out;}
 function keepPending(){if(owner&&!write(pendingKey(),{accountId:owner,revision,progress:snapshot(),pending:dirty,time:Date.now()}))status('Copie locale indisponible · garder le jeu ouvert');}
 function changed(){if(offline){write('owned-offline-progress-v1',{accountId:read(ownerKey),progress:snapshot(),time:Date.now()});return;}if(!ready)return;const encoded=JSON.stringify(snapshot());if(encoded===lastObserved)return;lastObserved=encoded;if(!owner){write(guestKey,JSON.parse(encoded));return;}dirty=encoded!==lastSaved;version++;keepPending();if(!blocked)schedule();}
 async function flush(){if(offline)return;clearTimeout(timer);timer=null;if(!owner||!dirty)return;if(blocked)throw Error(label);if(inflight){await inflight;if(dirty)return flush();return;}
  const data=snapshot(),encoded=JSON.stringify(data);
  if(encoded===lastSaved){dirty=false;lastObserved=encoded;keepPending();return;}
  inflight=(async()=>{try{const out=await api('POST',{accountId:owner,revision,progress:data});revision=out.revision;persistent=out.storage?.persistent===true;lastSaved=encoded;lastObserved=JSON.stringify(snapshot());dirty=lastObserved!==lastSaved;keepPending();status('Sauvegarde automatique activée');}
   catch(e){if(e.status===409||e.status===401){blocked=true;status('Session modifiée · copie locale conservée');}else status('Sauvegarde en attente · nouvelle tentative automatique');keepPending();throw e;}finally{inflight=null;}})();await inflight;schedule();
 }
 function apply(progress){G=Object.assign(fresh(),progress);G.paused=false;migrate(G);G.diff??=0;try{localStorage.removeItem('owned-saved-decks-v1');}catch{}write(SAVE_KEY,G);write(ownerKey,owner);}
 async function start(){
  dirty=false;blocked=false;
  if(location.protocol==='file:'){ready=true;return;}
  let out;try{out=await api('GET');}catch(e){if(e.status!==401)throw e;}
  const previous=read(ownerKey);
  if(!out){owner=null;if(previous){write('owned-account-backup:'+previous,snapshot());apply(read(guestKey)||fresh());}else{write(ownerKey,null);write(guestKey,snapshot());}ready=true;status('Profil local · connexion nécessaire');return;}
  owner=out.accountId;revision=out.revision;persistent=out.storage?.persistent===true;
  const pending=read(pendingKey());let progress=out.progress;
  if(pending?.pending&&pending.accountId===owner){
   if(pending.revision===revision){progress=pending.progress;dirty=true;}
   else {write('owned-conflict-backup:'+owner+':'+Date.now(),pending);if(!confirm('Une autre session a sauvegardé ce compte. Charger sa progression ? Ta copie locale sera conservée en secours.'))throw Error('Chargement annulé. Ferme l’autre session, puis réessaie.');}
  }
  if(!progress){const local=previous===owner?snapshot():!previous?(read(guestKey)||snapshot()):null;
   progress=local&&confirm('Ce compte n’a pas encore de progression en ligne. Lui associer la progression de cet appareil (niveau '+(local.lvl||1)+') ?')?local:fresh();dirty=true;
  }
  if(previous&&previous!==owner)write('owned-account-backup:'+previous,snapshot());
  apply(progress);lastObserved=JSON.stringify(snapshot());lastSaved=dirty?'':lastObserved;ready=true;keepPending();if(dirty)await flush();else status('Sauvegarde automatique activée');
 }
 function panel(){const box=document.createElement('div');box.className='cloud-save-panel';box.innerHTML='<p data-cloud-status role="status"></p><button class="btn glass" data-sync hidden>Réessayer</button>';paintStatus(box);box.querySelector('[data-sync]').onclick=async()=>{if(blocked){keepPending();location.reload();return;}try{await flush();}catch{}};return box;}
 async function boot(run){let gate=document.createElement('div');gate.className='cloud-boot';gate.innerHTML='<section><h2>Ta progression</h2><p role="status">Connexion à la sauvegarde…</p><button class="btn gold" hidden>Réessayer</button></section>';document.body.appendChild(gate);const attempt=async()=>{gate.querySelector('button').hidden=true;try{await start();gate.remove();run();}catch(e){if(e.status===503||e.status>=500||['TimeoutError','AbortError','TypeError','NetworkError'].includes(e.name)||e.message==='Le serveur de sauvegarde ne répond pas.'){offline=true;write('owned-offline-progress-v1',{accountId:read(ownerKey),progress:snapshot(),time:Date.now()});status('Mode local · sauvegarde en ligne indisponible');gate.remove();run();return;}gate.querySelector('p').textContent=e.message+' Ta progression locale est conservée.';gate.querySelector('button').hidden=false;}};gate.querySelector('button').onclick=attempt;await attempt();}
 addEventListener('online',()=>{if(ready&&dirty&&!blocked)flush().catch(()=>{});});
 addEventListener('pagehide',()=>{if(ready&&owner)keepPending();});
 addEventListener('beforeunload',e=>{if(dirty&&owner){keepPending();e.preventDefault();e.returnValue='';}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&ready&&dirty&&!blocked)flush().catch(()=>{});});
 setInterval(()=>{if(ready&&dirty&&!blocked)flush().catch(()=>{});},15000);
 return {boot,flush,changed,panel,get label(){return label;},get owner(){return owner;}};
})();

